workspace "Parcel Tracker" "C4 model of the parcel delivery tracking platform." {

    model {
        customer = person "Customer" "Looks up the status of their parcels on the platform."

        parcelTracker = softwareSystem "Parcel Tracker" "Parcel delivery tracking platform owned and operated by our company. Customers look up the status of their parcels and parcels are dispatched to couriers." {
            webPortal = container "Web Portal" "Web portal where customers look up shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "Service that assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Background service"
            database = container "Database" "Stores shipment and dispatch records." "SQL database"

            webPortal -> database "stores and retrieves shipment records in" "SQL"
            dispatchService -> database "stores and retrieves dispatch records in" "SQL"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Email delivery provider operated by a different organization. Delivers customer notification emails." "External"

        customer -> parcelTracker "looks up the status of their parcels in" "HTTPS/JSON"
        parcelTracker -> emailProvider "sends customer notification emails to" "REST/JSON"

        customer -> webPortal "looks up shipment status in" "HTTPS/JSON"
        dispatchService -> emailProvider "sends customer notification emails to" "REST/JSON"
    }

    views {
        systemContext parcelTracker "SystemContext" "System context diagram of the Parcel Tracker." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "Container diagram of the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}

